$string['serviceuser:policymissing'] = 'KI-Richtlinie NICHT akzeptiert';
$string['serviceuser_desc'] = 'Übersetzungen im Hintergrund brauchen ein Moodle-Konto, in dessen Namen die KI aufgerufen wird, weil Moodle KI nur für Personen erlaubt, die die KI-Richtlinie akzeptiert haben. Verwenden Sie ein eigenes Konto (der Einrichtungsassistent kann eines ohne Anmeldemöglichkeit anlegen) und akzeptieren Sie dafür die KI-Richtlinie. Ohne dieses Konto pausiert die automatische Übersetzung. "Jetzt übersetzen" im Editor läuft im Namen der Person, die klickt.';
$string['serviceuserfirstname'] = 'Inhalts';
$string['serviceuserlastname'] = 'Übersetzer';
$string['settings'] = 'Einstellungen';
$string['settings_intro'] = '<p>Übersetzt die Inhalte, die Trainer/innen und Admins erstellen (Namen und Beschreibungen von Kursen, Abschnitten und Aktivitäten, Textseiten, Buchkapitel, Buchungsoptionen, ...) mit KI in andere Sprachen. Die Übersetzung läuft im Hintergrund, bleibt innerhalb eines Monatsbudgets und wird jeder Person in ihrer eigenen Moodle-Sprache angezeigt. Die Originalinhalte werden nie verändert.</p><p>Zum ersten Mal hier? Beginnen Sie mit dem <a href="{$a->wizard}">Einrichtungsassistenten</a>. Fortschritt und Kosten: <a href="{$a->dashboard}">Website-Dashboard</a>.</p>';
$string['showoriginaltoggle'] = 'Umschalter "Original anzeigen"';
$string['showoriginaltoggle_desc'] = 'Zeigt auf übersetzten Seiten den Link "Original anzeigen", mit dem Lernende zwischen Original und Übersetzung wechseln können. Die Wahl gilt bis zur Abmeldung.';
$string['showstale'] = 'Veraltete Übersetzungen anzeigen';
$string['showstale_desc'] = 'Wird ein Originaltext geändert, ist seine Übersetzung veraltet, bis sie neu übersetzt ist (meist innerhalb weniger Minuten). An: Lernende sehen solange die alte Übersetzung. Aus: Sie sehen stattdessen das geänderte Original.';
$string['skipcolumns'] = 'Ausgelassene Felder von Aktivitäten';
$string['skipcolumns_desc'] = 'Textfelder, die "Alle Textfelder von Aktivitäten übersetzen" ignorieren soll, weil darin Einstellungen und keine Inhalte stehen. Ein Eintrag pro Zeile oder durch Kommas getrennt: "feld" gilt für alle Aktivitäten, "aktivität.feld" für eine Aktivität, * steht für beliebige Zeichen. Beispiel: lesson.conditions, lti.secureicon, *password*. Eine eingebaute Liste deckt die üblichen Fälle bereits ab.';
