$string['subtablemap'] = 'Zusätzliche Untertabellen (für Fachleute, JSON)';
$string['subtablemap_desc'] = 'Für Aktivitäten, die Inhalte in einer zweiten Tabelle speichern (wie die Kapitel eines Buchs), hier diese Tabelle beschreiben, damit sie mitübersetzt wird. Eingebaut sind: Buchkapitel, Abstimmungsoptionen, Lektionsseiten, Feedback-Fragen, Buchungsoptionen. Beispiel: {"book_chapters": {"module": "book", "parentfield": "bookid", "labelfield": "title", "restoremapping": "book_chapter", "fields": {"title": {"string": true, "format": 2}, "content": {"formatfield": "contentformat"}}}}';
